(function(){'use strict';
/* JAH The Electricians generator — jahdb-electricians-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed, same record. */
var PREFIX='JAH-ELTR-';
var FIELDS=["Foundations","Compounded","Advanced"];
var TOPICS=[{"tier": "Foundations", "g": "Electrical Basics", "title": "Ohm's Law in Practice", "desc": "Ohm's law - V = I*R - is the electrician's daily arithmetic: voltage pushes, resistance opposes, current results. The power law P = V*I completes it: a 120 V, 10 A load draws 1200 W. Every circuit calculation starts here - sizing wire for current, predicting voltage drop, checking breaker loading.\nIn practice the law runs three ways: find current from voltage and resistance (fault calculations), find voltage drop from current and resistance (wire sizing), find resistance from measurements (troubleshooting). Series circuits share current; parallel circuits share voltage. The electrician who can run Ohm's law fluently in both directions rarely miswires.", "how": "Electricians apply Ohm's law to size conductors (current from load power), verify voltage drop stays within limits (3% branch, 5% total per NEC guidance), and diagnose: measure voltage and current, compute the implied resistance, compare with expected. A motor drawing excess current at rated voltage has low effective resistance - overloaded or failing. The math is simple; applying it to the right circuit model is the skill.", "keys": ["V = I*R; P = V*I: the two equations of daily practice.", "Run the law three ways: current, voltage drop, resistance.", "Series shares current; parallel shares voltage.", "Voltage drop limits: 3% branch, 5% total.", "Measured V and I reveal the circuit's effective resistance."], "reqs": ["Circuit topology (series/parallel).", "Two of V, I, R known or measured.", "Load power for sizing calculations."], "stds": ["Voltage-drop guidance per NEC informational notes.", "Measurements with calibrated meters (CAT ratings)."], "cites": ["NFPA 70. National Electrical Code (NEC).", "Hartman T. Ugly's Electrical References. Jones & Bartlett."], "demo": "#!/usr/bin/env python3\n\"\"\"Ohm law: circuit values from any two.\"\"\"\nV, R = 120.0, 12.0\nI = V / R\nprint(f\"V={V}V, R={R}ohm -> I={I:.1f}A, P={V*I:.0f}W\")\n# voltage drop on 100 ft of 12 AWG (1.588 ohm/1000ft) at 16A\nRwire = 2 * 1.588 / 1000 * 100\nprint(f\"VD = {16*Rwire:.2f} V ({16*Rwire/120*100:.1f}%)\")\n"}, {"tier": "Foundations", "g": "Electrical Basics", "title": "Series and Parallel Circuits", "desc": "Series circuits chain loads end to end: current is identical through all, voltages divide by resistance, and one break kills everything - Christmas lights of old. Parallel circuits branch across the same voltage: each branch draws its own current, total current sums, and one branch can fail while others run - how buildings are wired.\nResidential wiring is parallel: every receptacle sees 120 V independently. Series appears in switch legs, three-way travelers, and some control circuits. Troubleshooting uses the topology: in series, find the open by voltage division; in parallel, find the shorted branch by current. Misidentifying topology is the root of most wiring confusion.", "how": "Electricians wire buildings in parallel for independent operation, use series for switching and controls, and compute equivalents: R_series sums, 1/R_parallel sums reciprocally. They troubleshoot by topology - half-splitting series strings to find opens, clamping parallel branches to find overloads. Voltage measurements across series elements reveal the bad one (full voltage across the open). The panel schedule documents which parallel branches exist.", "keys": ["Series: same current, divided voltage, one break kills all.", "Parallel: same voltage, summed current, branches independent.", "Buildings wire in parallel; switches wire in series.", "R_series sums; conductances sum in parallel.", "Troubleshoot by topology: opens in series, shorts in parallel."], "reqs": ["Circuit topology identification.", "Branch resistances or loads.", "Measurement plan (voltage vs current)."], "stds": ["Circuit analysis per standard electrical theory.", "Panel schedules per NEC 408.4."], "cites": ["NFPA 70. National Electrical Code (NEC).", "Grob B. Basic Electronics. McGraw-Hill."], "demo": "#!/usr/bin/env python3\n\"\"\"Series vs parallel: three 60W-equivalent loads at 120V.\"\"\"\nR_each = 120.0 ** 2 / 60  # ohms per 60W load\nR_series = 3 * R_each\nR_par = R_each / 3\nprint(f\"Series: {120/R_series:.2f} A total, {120**2/R_series:.0f} W (dim!)\")\nprint(f\"Parallel: {120/R_par:.1f} A total, {120**2/R_par:.0f} W\")\n"}, {"tier": "Foundations", "g": "Electrical Basics", "title": "AC vs DC", "desc": "Direct current flows one way - batteries, solar, electronics. Alternating current reverses direction periodically - 60 Hz in North America, 50 Hz most elsewhere - which is what the grid delivers and what buildings use. AC's advantage is transformation: voltages step up for efficient transmission and down for safe use, which is why AC won the War of Currents.\nAC brings RMS values (120 V RMS peaks at 170 V), phase relationships, power factor (real vs apparent power), and skin effect. DC brings polarity discipline and battery/storage logic. Modern work mixes both: solar and batteries are DC, buildings are AC, and inverters bridge them. Electricians respect each: AC bites with let-go thresholds, DC arcs sustain stubbornly.", "how": "Electricians work AC for premises wiring (NEC Article 210-250 world) and DC for solar, battery, and controls, keeping the disciplines separate: AC color codes and phasing vs DC polarity and arc-fault behavior. They size inverters for solar/battery integration, understand power factor for commercial billing, and test with meters set to the right mode - measuring DC on AC settings is a classic error. Safety: AC let-go current ~10-20 mA; DC arcs do not self-extinguish.", "keys": ["DC flows one way; AC alternates (60 Hz North America).", "AC transforms efficiently - the grid's choice.", "RMS values: 120 V RMS peaks at 170 V.", "Modern work mixes both: solar/battery DC, premises AC.", "Meter on the wrong mode is a classic error."], "reqs": ["System type identification (AC/DC, voltage, frequency).", "Correct meter mode and CAT rating.", "Polarity/phasing discipline."], "stds": ["AC systems per NEC; DC per NEC Article 690/706 (solar/storage).", "Frequency 60 Hz per North American grid standards."], "cites": ["NFPA 70. National Electrical Code (NEC).", "Hartman T. Ugly's Electrical References. Jones & Bartlett."], "demo": "#!/usr/bin/env python3\n\"\"\"AC RMS vs peak; DC equivalent power.\"\"\"\nimport math\nVrms = 120.0\nprint(f\"{Vrms} Vrms -> peak {Vrms*math.sqrt(2):.0f} V, peak-to-peak {2*Vrms*math.sqrt(2):.0f} V\")\n# power factor effect\nfor pf in (1.0, 0.8, 0.6):\n    print(f\"  10A at PF={pf}: real {120*10*pf:.0f} W, apparent {120*10:.0f} VA\")\n"}, {"tier": "Foundations", "g": "Reading & Tools", "title": "Reading Electrical Blueprints", "desc": "Electrical blueprints translate design intent into installation: floor plans show device locations, riser diagrams show distribution from service to panels to loads, schedules list panelboards with breaker sizes and loads, and details show mounting and wiring methods. Symbols (receptacle, switch, light, panel) follow standard legends - every set has one; read it first.\nThe electrician cross-references: plans for location, schedules for sizing, specs for materials, details for how. Revisions cloud changes; RFIs resolve conflicts before rough-in. BIM models now carry the same data in 3D with clash detection against ductwork and plumbing - the modern blueprint.", "how": "Electricians start with the legend and general notes, then trace power from the service through risers to each panel, checking schedules against plans for every circuit. They flag conflicts (missing neutrals, overloaded panels, unreachable devices) as RFIs before rough-in. Takeoffs count devices and estimate wire from homerun lengths. As-builts mark what changed - the document the next electrician depends on.", "keys": ["Plans locate; risers distribute; schedules size; details show how.", "Read the legend and notes first.", "Trace power service to load on every job.", "RFIs resolve conflicts before rough-in.", "Takeoffs count devices; as-builts record changes."], "reqs": ["Complete plan set with legend and schedules.", "Spec section for materials.", "Revision control (clouds, RFIs)."], "stds": ["Symbols per IEEE 315 / NEMA standards.", "BIM per NBIMS-US where applicable."], "cites": ["NFPA 70. National Electrical Code (NEC).", "Muller F. Electrical Blueprint Reading."], "demo": "#!/usr/bin/env python3\n\"\"\"Takeoff: device count from a plan list.\"\"\"\ndevices = {\"duplex receptacle\": 42, \"single-pole switch\": 18, \"3-way switch\": 6,\n           \"recessed light\": 30, \"smoke detector\": 8}\ntotal = sum(devices.values())\nprint(f\"Device takeoff: {total} devices\")\nfor d, n in devices.items():\n    print(f\"  {d:20s}: {n}\")\n"}, {"tier": "Foundations", "g": "Wiring & Devices", "title": "Wire Types and Sizing", "desc": "Wire sizing matches conductor ampacity to load with code guardrails: 14 AWG for 15 A, 12 AWG for 20 A, 10 AWG for 30 A in typical residential (NEC Table 310.16 with derating). Insulation types suit environments - THHN/THWN in conduit, NM-B (Romex) in dry residential walls, UF for direct burial, XHHW for heat.\nDerating shrinks ampacity: more than three current-carrying conductors in a raceway, high ambient temperature, or continuous loads (125% sizing) all apply. Aluminum needs larger sizes and compatible devices (CO/ALR) with antioxidant. Stranded wire flexes for conduit pulls; solid is standard for small residential branch circuits.", "how": "Electricians compute load current, apply the 125% continuous-load factor, select insulation for the environment, then check Table 310.16 and apply derating for conductor count and ambient temperature - the smallest wire satisfying all three wins. They upsize for long runs where voltage drop governs instead of ampacity. Terminations match wire type: torque to spec (NEC 110.14 now enforced), aluminum with compatible devices and compound.", "keys": ["14/12/10 AWG for 15/20/30 A typical residential.", "Insulation matched to environment: THHN, NM-B, UF, XHHW.", "Derate for conductor count, ambient temperature, continuous loads.", "Continuous loads sized at 125%.", "Torque terminations to spec; aluminum needs compatible devices."], "reqs": ["Load current and continuous/noncontinuous classification.", "Environment (wet, dry, burial, temperature).", "Raceway fill and ambient for derating."], "stds": ["Ampacity per NEC Table 310.16.", "Termination torque per NEC 110.14(D)."], "cites": ["NFPA 70. National Electrical Code (NEC).", "Hartman T. Ugly's Electrical References. Jones & Bartlett."], "demo": "#!/usr/bin/env python3\n\"\"\"Derated ampacity: 6 current-carrying 12 AWG THHN in conduit.\"\"\"\nbase = 30.0  # 12 AWG THHN at 90C column\nderate_count, derate_temp = 0.80, 0.91  # 4-6 conductors; 40C ambient\namp = base * derate_count * derate_temp\nprint(f\"Derated: {amp:.1f} A (protect at next standard <= 20A for branch circuits)\")\n"}, {"tier": "Foundations", "g": "Code & Safety", "title": "The National Electrical Code Structure", "desc": "The NEC (NFPA 70) is the electrician's law book, organized in nine chapters: 1-4 general (definitions, wiring, protection), 5-7 special (occupancies, equipment, conditions), 8 communications, 9 tables. Articles group by topic - 210 branch circuits, 250 grounding, 300 wiring methods, 310 conductors, 408 panelboards, 690 solar.\nCode language is precise: 'shall' means mandatory, 'shall be permitted' means allowed. Exceptions modify rules; informational notes explain but do not bind. The NEC is revised every three years and adopted with local amendments - the AHJ (authority having jurisdiction) has the final word. Knowing where to find a rule beats memorizing it.", "how": "Electricians navigate by article: identify the installation type, find the governing article, read the rule plus exceptions, check for local amendments. They tab the codebook's high-traffic articles and tables (310.16, 250.66/122, Chapter 9 conduit fill). Continuing education tracks code cycles; inspectors enforce the locally adopted edition. When in doubt, ask the AHJ before rough-in - after is expensive.", "keys": ["Nine chapters; articles by topic (210, 250, 300, 310...).", "'Shall' is mandatory; notes inform but do not bind.", "Revised every 3 years; local amendments apply.", "The AHJ has the final word.", "Navigate by article; tab the high-traffic tables."], "reqs": ["Locally adopted NEC edition.", "Article identification for the installation.", "AHJ interpretations where ambiguous."], "stds": ["NFPA 70 National Electrical Code.", "Local amendments and AHJ rulings."], "cites": ["NFPA 70. National Electrical Code (NEC).", "Hartman T. Ugly's Electrical References. Jones & Bartlett."], "demo": "#!/usr/bin/env python3\n\"\"\"NEC article lookup map (common).\"\"\"\narticles = {\"210\": \"branch circuits\", \"250\": \"grounding/bonding\", \"300\": \"wiring methods\",\n            \"310\": \"conductors\", \"408\": \"panelboards\", \"430\": \"motors\",\n            \"690\": \"solar PV\", \"700\": \"emergency systems\"}\nfor a, t in articles.items():\n    print(f\"  Article {a}: {t}\")\n"}, {"tier": "Foundations", "g": "Code & Safety", "title": "Grounding and Bonding Basics", "desc": "Grounding connects the electrical system to earth; bonding connects metal parts together so fault current has a low-impedance path back to trip the breaker. The equipment grounding conductor (green/bare) bonds device boxes and frames; the grounding electrode system (rods, water pipe, concrete-encased) ties the service to earth.\nThe grounded (neutral) conductor carries normal return current; the grounding conductor carries only fault current - confusing them creates objectionable current and shock hazards. Main bonding jumper connects neutral to ground at the service (once); subpanels keep them separate. Ground faults must clear fast: the fault path impedance decides whether the breaker trips or the enclosure stays energized.", "how": "Electricians install the electrode system per 250.52, size grounding electrode conductors by 250.66 and equipment grounds by 250.122, bond all metal piping and structural steel, and verify continuity of the fault path. They keep neutral and ground separate past the service disconnect (the most violated rule), torque bonding connections, and test ground-fault paths where critical. Megger and ground-resistance testers verify electrodes.", "keys": ["Grounding ties to earth; bonding ties metal together.", "Equipment ground carries fault current to trip the breaker.", "Neutral and ground bond once - at the service.", "Subpanels keep neutral and ground separate.", "Low-impedance fault path is what clears faults fast."], "reqs": ["Electrode system per 250.52.", "Conductor sizing per 250.66/122.", "Neutral-ground separation past the service."], "stds": ["Grounding per NEC Article 250.", "Ground resistance per IEEE 81."], "cites": ["NFPA 70. National Electrical Code (NEC).", "Hartman T. Ugly's Electrical References. Jones & Bartlett."], "demo": "#!/usr/bin/env python3\n\"\"\"Equipment ground sizing (NEC 250.122 hint).\"\"\"\ntable = [(15, 14), (20, 12), (30, 10), (60, 10), (100, 8), (200, 6)]\nprint(\" breaker (A)   ground AWG (Cu)\")\nfor brk, awg in table:\n    print(f\"    {brk:3d}         {awg}\")\n"}, {"tier": "Foundations", "g": "Wiring & Devices", "title": "Boxes, Enclosures, and Fill", "desc": "Every splice and device lives in a box - the fire containment and access rule. Box fill (NEC 314.16) limits conductors per box volume: each conductor counts by size (2.0 in3 for 14 AWG, 2.25 for 12 AWG), devices count double, clamps and grounds count too. Overfilled boxes overheat and fail inspection.\nBox types suit the job: handy and 4-inch square for commercial, plastic nail-ons for residential, weatherproof with gaskets outdoors, deep boxes for GFCI/AFCI devices. Covers must remain accessible - burying a box behind drywall without access violates code and common sense. Enclosures (NEMA ratings) protect equipment: NEMA 1 indoor, 3R outdoor rainproof, 4X corrosive.", "how": "Electricians count box fill before closing: conductors, devices (2x), clamps, grounds per 314.16, choosing the next size up when close. They set boxes flush or proud per surface, support them independently of the device, and keep every box accessible with a cover. Outdoor and wet locations get weatherproof boxes with proper hubs. Fill calculations are documented for the inspector on large commercial jobs.", "keys": ["Every splice in a box - fire containment and access.", "Box fill per 314.16: count conductors, devices (2x), clamps, grounds.", "Boxes must stay accessible - never bury without a cover.", "Match box type to location: indoor, weatherproof, deep.", "NEMA ratings protect equipment by environment."], "reqs": ["Conductor count and sizes for fill calc.", "Location (dry, damp, wet).", "Accessibility after finish."], "stds": ["Box fill per NEC 314.16.", "Enclosure ratings per NEMA 250."], "cites": ["NFPA 70. National Electrical Code (NEC).", "Hartman T. Ugly's Electrical References. Jones & Bartlett."], "demo": "#!/usr/bin/env python3\n\"\"\"Box fill: 4x12AWG + device + ground (in3).\"\"\"\nper = {14: 2.0, 12: 2.25, 10: 2.5}\nfill = 4 * per[12] + 2 * per[12] + 1 * per[12]  # conductors + device(2x) + ground\nprint(f\"Fill = {fill:.2f} in3 -> 4-in square x 2-1/8 in (30.3 in3) OK\")\n"}, {"tier": "Foundations", "g": "Wiring & Devices", "title": "Receptacles and Switches", "desc": "Receptacles and switches are the user interface of the electrical system. Duplex receptacles (NEMA 5-15R) deliver 15 A at 125 V; 20 A receptacles (5-20R) take the T-neutral plug. Tamper-resistant receptacles are code in dwellings; GFCI protection guards wet locations; AFCI guards bedrooms. Switches break the hot, never the neutral - single-pole for one location, three-way pairs for two, four-way between for more.\nWiring discipline: pigtail neutrals so removing a device does not break downstream continuity, wrap clockwise around screws, torque to spec, and keep box fill legal. Backstabbed connections fail - the trade's shared scar tissue. Dimmer and smart switches need neutrals increasingly; check the box before promising.", "how": "Electricians wire receptacles with pigtails (line in, line out, device), keeping downstream alive during device replacement; they land hots on brass, neutrals on silver, grounds on green, and torque screws. Three-ways get travelers on the brass screws and common identified - the most miswired device in houses. They test every device: correct wiring, GFCI trip, voltage under load. AFCI/GFCI placement follows 210.8 and 210.12.", "keys": ["Receptacles: 15 A duplex standard; TR in dwellings; GFCI wet, AFCI bedrooms.", "Switches break the hot, never the neutral.", "Pigtail neutrals - device removal must not break downstream.", "Three-ways: travelers brass, common identified.", "Backstabs fail; torque screws to spec."], "reqs": ["Circuit rating matching device rating.", "GFCI/AFCI placement per 210.8/210.12.", "Neutral availability for smart devices."], "stds": ["Device wiring per NEC Article 404/406.", "GFCI/AFCI per NEC 210.8/210.12."], "cites": ["NFPA 70. National Electrical Code (NEC).", "Hartman T. Ugly's Electrical References. Jones & Bartlett."], "demo": "#!/usr/bin/env python3\n\"\"\"Receptacle load check: 180VA per yoke (commercial hint).\"\"\"\nreceptacles, va_each = 12, 180\nload_va = receptacles * va_each\ncircuits = load_va / (20 * 120)\nimport math\nprint(f\"{receptacles} receptacles = {load_va} VA -> {math.ceil(circuits)} x 20A circuits\")\n"}, {"tier": "Foundations", "g": "Wiring & Devices", "title": "Lighting Circuits", "desc": "Lighting circuits are the most numerous in buildings: 15-20 A branch circuits feeding fixtures through switches, with load calculated at 125% for continuous operation. LED retrofits slashed lighting loads - a floor that needed six circuits now needs two - but introduced drivers, dimming compatibility, and inrush considerations.\nControls have their own code: energy codes (IECC, Title 24) require occupancy/vacancy sensors, daylight harvesting, and multi-level switching in commercial spaces. Emergency lighting (NEC 700) rides separate circuits with battery or generator backup. Dimming protocols (0-10 V, DALI, wireless) must match drivers - mismatched dimming flickers or fails.", "how": "Electricians lay out lighting by footcandle targets and fixture photometrics, circuit at 80% of breaker for continuous loads, and wire controls per the energy code: sensors, daylight zones, and emergency circuits separated and identified. They verify dimmer-driver compatibility on the first fixture before roughing a hundred, and commission controls (aim sensors, set time delays) - uncommissioned controls are the top lighting complaint. Emergency circuits get red devices or labels.", "keys": ["Size at 125% for continuous lighting loads.", "LEDs cut loads but add driver/dimming discipline.", "Energy codes require sensors, daylighting, multi-level control.", "Emergency lighting rides separate backed-up circuits.", "Verify dimmer-driver compatibility before rough-in."], "reqs": ["Footcandle targets and fixture photometrics.", "Energy-code control requirements.", "Emergency lighting coverage."], "stds": ["Lighting per NEC 210/220; emergency per NEC 700.", "Energy per IECC / ASHRAE 90.1."], "cites": ["NFPA 70. National Electrical Code (NEC).", "IES Lighting Handbook. 10th ed."], "demo": "#!/usr/bin/env python3\n\"\"\"Lighting load: LED retrofit circuit count.\"\"\"\nfixtures, watts_old, watts_led = 60, 64.0, 28.0\nfor w, label in ((watts_old, \"fluorescent\"), (watts_led, \"LED\")):\n    va = fixtures * w * 1.25\n    import math\n    print(f\"  {label:12s}: {va:.0f} VA -> {math.ceil(va/(20*120))} x 20A circuits\")\n"}, {"tier": "Foundations", "g": "Reading & Tools", "title": "Using a Multimeter", "desc": "The multimeter is the electrician's truth-teller: voltage (parallel across), current (series, or clamp around), resistance/continuity (de-energized only). CAT ratings (II, III, IV) certify the meter's transient withstand by location - service entrance needs CAT IV; using a CAT II meter there risks arc flash.\nTechnique: test the tester on a known source before and after (live-dead-live), keep one hand behind when possible, and never measure resistance on energized circuits. Clamp meters read current without breaking the circuit - the daily workhorse. NCVTs (non-contact testers) screen for presence; meters confirm value.", "how": "Electricians verify meters with live-dead-live before trusting a 'dead' reading, select CAT-rated meters for the location, and measure voltage phase-to-phase and phase-to-ground to characterize the system. They clamp running currents to find overloads, check continuity on de-energized conductors to find opens, and megger insulation where failure is suspected. Every measurement is documented when it decides a diagnosis.", "keys": ["Voltage across, current through (or clamp), resistance de-energized only.", "CAT rating must suit the location - CAT IV at the service.", "Live-dead-live: prove the tester before trusting dead.", "Clamp meters read current without breaking circuits.", "NCVT screens; the meter confirms."], "reqs": ["CAT-rated meter for the location.", "Known source for live-dead-live.", "De-energized state for resistance/continuity."], "stds": ["Meter safety per IEC 61010 CAT ratings.", "Testing per NFPA 70E practices."], "cites": ["NFPA 70E. Standard for Electrical Safety in the Workplace.", "Fluke. Electrical measurement safety guidance."], "demo": "#!/usr/bin/env python3\n\"\"\"Live-dead-live checklist state machine.\"\"\"\nsteps = [\"test meter on known live source -> reads voltage\",\n         \"test de-energized circuit -> reads 0\",\n         \"retest meter on known live source -> reads voltage\"]\nfor i, s in enumerate(steps, 1):\n    print(f\"  {i}. {s}\")\nprint(\"All three pass -> circuit verified dead\")\n"}, {"tier": "Foundations", "g": "Code & Safety", "title": "Electrical Safety and PPE", "desc": "Electricity kills by arc flash and shock: NFPA 70E structures the defense - establish an electrically safe work condition (lockout/tagout, verified dead) whenever possible; when live work is justified, use shock and arc-flash boundaries, insulated tools, and arc-rated PPE matched to the incident energy.\nShock boundaries (limited, restricted) keep unqualified people back; the arc-flash boundary marks where burns become likely. PPE categories (1-4, cal/cm2 ratings) follow the arc-flash study. GFCI protection for construction power, ladder safety around overheads, and never working alone on energized gear are field rules written in injuries.", "how": "Electricians default to de-energized work: notify, open, lock, tag, verify with live-dead-live, ground where required. When live work is justified and permitted, they wear the arc rating the study calls for, use insulated tools, and keep one qualified person as attendant. They read the arc-flash labels before opening gear, maintain approach boundaries, and treat every conductor as live until proven otherwise - complacency is the hazard behind the hazard.", "keys": ["De-energize and verify: the default, not the exception.", "NFPA 70E: boundaries, PPE, and the electrically safe work condition.", "Arc-flash PPE rated in cal/cm2, matched to incident energy.", "GFCI on construction power; never work energized alone.", "Treat every conductor as live until proven otherwise."], "reqs": ["Lockout/tagout equipment and procedures.", "Arc-flash study and labeled gear.", "Cal-rated PPE and insulated tools."], "stds": ["NFPA 70E Standard for Electrical Safety in the Workplace.", "Lockout/tagout per OSHA 1910.147."], "cites": ["NFPA 70E. Standard for Electrical Safety in the Workplace.", "OSHA 29 CFR 1910 Subpart S."], "demo": "#!/usr/bin/env python3\n\"\"\"Approach boundaries (illustrative, 480V).\"\"\"\nprint(\"  limited approach: 3 ft 6 in (unqualified)\")\nprint(\"  restricted approach: 1 ft 0 in (qualified, PPE)\")\nprint(\"  arc-flash boundary: per incident-energy study\")\n"}, {"tier": "Compounded", "g": "Panels & Distribution", "title": "Service Panels and Load Calculations", "desc": "The service panel is the building's electrical heart: service conductors land on the main breaker, bus bars distribute to branch breakers, neutrals and grounds terminate on their bars (bonded only here). Load calculations (NEC Article 220) size the service: general lighting at 3 VA/ft2, small-appliance and laundry circuits, fixed appliances at nameplate, HVAC at largest of heating/cooling, with demand factors recognizing not everything runs at once.\nThe standard method tallies everything; the optional method simplifies dwellings. Services come in standard sizes - 100, 200, 400 A residential; commercial to thousands of amps with switchgear. Working clearances (110.26: 3 ft deep, 6.5 ft high, 30 in wide) keep the panel serviceable and legal. Every panel gets a directory - NEC 408.4, no mysteries.", "how": "Electricians run Article 220 calcs from the plans, select the next standard service size up, and verify the utility can deliver it (service lateral, transformer). They lay out panels with spare capacity (20% minimum good practice), keep working clearances clear of storage and plumbing, torque every termination, and label every circuit in the directory. Load calcs are submitted for permit; inspectors check service size against them first.", "keys": ["Service panel: main breaker, buses, neutral/ground bonded once.", "Article 220 sizes the service: lighting, appliances, HVAC, demands.", "Standard sizes: 100/200/400 A residential; switchgear commercial.", "Working clearances 110.26: 3 ft deep, 6.5 ft high, 30 in wide.", "Every panel gets a real directory - no mysteries."], "reqs": ["Floor area, appliance nameplates, HVAC loads.", "Demand factors per Article 220.", "Utility service availability."], "stds": ["Load calcs per NEC Article 220.", "Working space per NEC 110.26; directories per 408.4."], "cites": ["NFPA 70. National Electrical Code (NEC).", "Hartman T. Ugly's Electrical References. Jones & Bartlett."], "demo": "#!/usr/bin/env python3\n\"\"\"Dwelling load calc, standard method (simplified VA).\"\"\"\nsqft = 2000.0\nlighting = sqft * 3\nsmall_appl = 2 * 1500\nlaundry = 1500\nappliances = 8000 + 4500  # range + dryer (nameplate-ish)\nhvac = 12000  # larger of heat/cool\nsubtotal = lighting + small_appl + laundry\ndemand = 3000 + 0.35 * max(0, subtotal - 3000)\ntotal = demand + appliances + hvac\namps = total / 240\nprint(f\"Total {total:.0f} VA -> {amps:.0f} A: use 200A service\")\n"}, {"tier": "Compounded", "g": "Panels & Distribution", "title": "Branch Circuit Design", "desc": "Branch circuits run from the final breaker to the loads: 15-20 A general purpose, dedicated circuits for laundry, bathroom, kitchen small-appliance (two minimum), and individual circuits for fixed equipment (HVAC, water heater, range). Multiwire branch circuits share a neutral between opposite phases - efficient but demanding handle-tied breakers and careful neutral discipline.\nDesign balances loads across phases (commercial), limits outlets per circuit by load calc (not arbitrary counts), and routes homeruns efficiently. Dedicated means dedicated - a microwave on the bathroom circuit is a callback. AFCI/GFCI requirements attach by location, and the 2020+ cycles keep expanding them.", "how": "Electricians lay out branch circuits from the load calc, dedicating per code (kitchen, laundry, bath, equipment), balancing phases in commercial panels, and choosing AFCI/GFCI breakers or devices by location. They keep multiwire neutrals pigtailed and handle-tied, route homeruns to minimize wire, and verify each circuit's loads against breaker rating at trim. The panel directory documents the design for the next person.", "keys": ["Branch circuits: general, dedicated, and multiwire types.", "Kitchens need two small-appliance circuits; baths and laundry dedicated.", "Multiwire shares neutral across phases - handle ties required.", "Balance phases in commercial panels.", "AFCI/GFCI attach by location; cycles keep expanding them."], "reqs": ["Load calc per circuit.", "Location-based protection requirements.", "Phase balancing plan (3-phase)."], "stds": ["Branch circuits per NEC 210.", "Multiwire per NEC 210.4."], "cites": ["NFPA 70. National Electrical Code (NEC).", "Hartman T. Ugly's Electrical References. Jones & Bartlett."], "demo": "#!/usr/bin/env python3\n\"\"\"Phase balancing check: 3-phase panel loads.\"\"\"\nphases = {\"A\": [1800, 1500, 900], \"B\": [2000, 1200], \"C\": [1600, 1600, 700]}\ntotals = {p: sum(v) for p, v in phases.items()}\nfor p, t in totals.items():\n    print(f\"  Phase {p}: {t} VA\")\nmx, mn = max(totals.values()), min(totals.values())\nprint(f\"  Imbalance: {(mx-mn)/mx*100:.0f}% (rebalance if large)\")\n"}, {"tier": "Compounded", "g": "Protection", "title": "GFCI and AFCI Protection", "desc": "GFCIs save lives from ground faults: they compare hot and neutral current and trip at 4-6 mA imbalance - before a fault through a person becomes lethal. Required in bathrooms, kitchens, garages, outdoors, crawlspaces, basements, laundry, and near sinks/showers (210.8, expanding every cycle). AFCIs prevent fires from arcing faults: they listen for the RF signature of dangerous arcs and trip, required in dwelling living areas (210.12).\nNuance matters: GFCI protects people (fast, sensitive); AFCI protects property (pattern recognition). Dual-function breakers do both. Nuisance tripping usually means a real problem - shared neutrals, damaged insulation, or incompatible equipment. Test monthly; replace when the test fails.", "how": "Electricians place GFCI protection by 210.8 location list - breaker or device, first in line protecting downstream - and AFCI by 210.12 for dwelling living spaces. They wire with attention to neutrals: GFCI/AFCI devices need their own neutral path, no sharing downstream. They test at trim with the test button and a plug-in tester, and troubleshoot trips by isolating: unplug loads, megger the wiring, check for neutral-ground bonds. Document locations for the homeowner.", "keys": ["GFCI trips at 4-6 mA imbalance - protects people.", "AFCI detects arc signatures - protects property from fire.", "210.8 lists GFCI locations; 210.12 lists AFCI spaces.", "No shared neutrals downstream of GFCI/AFCI devices.", "'Nuisance' trips usually mean real problems - investigate."], "reqs": ["Location list compliance (210.8/210.12).", "Dedicated neutral paths downstream.", "Test-and-document at trim."], "stds": ["GFCI per UL 943; AFCI per UL 1699.", "Placement per NEC 210.8/210.12."], "cites": ["NFPA 70. National Electrical Code (NEC).", "UL 943. Ground-Fault Circuit-Interrupters."], "demo": "#!/usr/bin/env python3\n\"\"\"GFCI imbalance detection (mA).\"\"\"\nfor hot, neutral in ((5000, 5000), (5000, 4996), (5000, 4980)):\n    imb = hot - neutral\n    print(f\"  hot {hot} mA, neutral {neutral}: imbalance {imb} mA -> {\"TRIP\" if imb >= 5 else \"ok\"}\")\n"}, {"tier": "Compounded", "g": "Wiring Methods", "title": "Conduit Bending: EMT", "desc": "EMT (electrical metallic tubing) is the thinwall workhorse of commercial wiring, bent in the field with hand benders: 90-degree stubs, offsets (two equal bends to dodge obstacles), saddles (three or four bends over pipes), and kicks. The bender's arrow, star, and rim notch mark bend points; the take-up (deduct) per size is memorized - 5 inches for 1/2-inch 90s.\nCode limits: 360 degrees total bend between pull points (314.71-era practice: keep it well under), minimum bend radius, and reaming to remove burrs that would skin wire insulation. Couplings and connectors must be concrete-tight or raintight by location. Good bending is layout plus repetition - measure twice, bend once, and keep runs parallel and plumb.", "how": "Electricians plan runs to minimize bends and keep under 360 degrees between boxes, mark bend points with the deduct for the bender size, and bend in sequence (stub, then offset legs). They ream every cut, tighten set-screw or compression fittings to spec, support per 358.30 (within 3 ft of boxes, 10 ft intervals), and pull with lube and a helper feeding - never yank. Parallel runs share layout lines for the clean look inspectors and customers notice.", "keys": ["EMT bends: 90s, offsets, saddles, kicks - hand bender skills.", "Deduct/take-up memorized per bender size.", "Max 360 degrees bend between pull points.", "Ream every cut - burrs skin insulation.", "Support within 3 ft of boxes, 10 ft on runs."], "reqs": ["Bender matched to conduit size.", "Run layout minimizing total bend.", "Fittings rated for the location."], "stds": ["EMT per NEC Article 358.", "Supports per NEC 358.30."], "cites": ["NFPA 70. National Electrical Code (NEC).", "Cox R. Electrician's Guide to Conduit Bending."], "demo": "#!/usr/bin/env python3\n\"\"\"Offset bend: travel between marks.\"\"\"\nimport math\n# offset depth d, bend angle a: travel = d / sin(a)\nd_in = 6.0\nfor a_deg in (10, 22.5, 30, 45):\n    travel = d_in / math.sin(math.radians(a_deg))\n    print(f\"  {a_deg:4.1f} deg bends: mark spacing {travel:.1f} in\")\n"}, {"tier": "Compounded", "g": "Wiring & Devices", "title": "Three-Way and Four-Way Switching", "desc": "Three-way switches control a light from two locations: two traveler wires run between the switches, each three-way toggling which traveler connects to the common. Power feeds the common of the first, the light hangs on the common of the second. Four-way switches go between the three-ways, swapping the travelers, adding locations indefinitely.\nThe classic miswire: landing travelers and common wrong makes the circuit work 'sometimes' - the tell of a misidentified common. Modern code often wants a neutral in switch boxes (404.2(C)) for smart switches; dead-end three-ways complicate that. Smart switches can replace travelers with wireless, but wired three-ways remain the reliable standard.", "how": "Electricians identify the common by continuity (the terminal that toggles between travelers), land power and switch-leg on commons, travelers on the traveler screws, and verify from both locations before closing. They pull neutrals to switch boxes per 404.2(C), keep travelers in the same cable to avoid inductive heating, and label in multi-gang boxes. Four-ways are tested from every location - each must toggle the light.", "keys": ["Three-ways: two travelers between, commons carry power and switch-leg.", "Four-ways swap travelers between three-ways for more locations.", "Misidentified common = works 'sometimes'.", "Neutrals in switch boxes per 404.2(C) for smart devices.", "Test from every location before closing."], "reqs": ["Traveler pair in the same cable.", "Common identification by test.", "Neutral at switch locations."], "stds": ["Switches per NEC Article 404.", "Neutral requirement per NEC 404.2(C)."], "cites": ["NFPA 70. National Electrical Code (NEC).", "Hartman T. Ugly's Electrical References. Jones & Bartlett."], "demo": "#!/usr/bin/env python3\n\"\"\"Three-way truth table (switch A, switch B -> light).\"\"\"\nprint(\"  A   B   light\")\nfor a in (0, 1):\n    for b in (0, 1):\n        print(f\"  {a}   {b}    {\"ON\" if a == b else \"OFF\"}\")\n"}, {"tier": "Compounded", "g": "Motors", "title": "Motor Controls Basics", "desc": "Motor control is switching plus protection: contactors (heavy-duty relays) switch motor current, overload relays guard against sustained overcurrent, and control circuits (start/stop stations, often 120 V) drive the contactor coil. The three-wire control with seal-in contact is the foundation - momentary start energizes the coil, the auxiliary contact seals it until stop.\nOverloads are sized to motor FLA (430.32); short-circuit protection (breaker/fuses) guards the wiring. Ladder diagrams read left to right, top to bottom - the electrician's logic schematic. Across-the-line starting is simplest; reduced-voltage (soft start, VFD) limits inrush where the utility or mechanics demand it.", "how": "Electricians read the ladder diagram, wire power (contactor, overload, motor) and control (start/stop, coil) separately, set overloads to FLA, and test the seal-in logic before coupling the load. They verify rotation, measure running current against nameplate, and check that stop actually stops (safety). Schematics stay in the panel door for the next troubleshooter. VFDs add parameter setup and motor-lead filtering to the skill set.", "keys": ["Contactor switches; overload relay protects; control circuit commands.", "Three-wire seal-in: start seals through its own auxiliary contact.", "Overloads sized to motor FLA per 430.32.", "Ladder diagrams read left to right, top to bottom.", "Verify stop stops - safety before production."], "reqs": ["Motor nameplate (FLA, voltage, phase).", "Ladder diagram for the control scheme.", "Overload and short-circuit protection sizing."], "stds": ["Motors per NEC Article 430.", "Control panels per UL 508A."], "cites": ["NFPA 70. National Electrical Code (NEC).", "Herman SL. Industrial Motor Control. Cengage."], "demo": "#!/usr/bin/env python3\n\"\"\"Motor FLA from HP (460V 3-phase hint).\"\"\"\n# FLA ~= HP*746/(V*1.73*eff*pf)\nfor hp in (5, 10, 25, 50):\n    fla = hp * 746 / (460 * 1.73 * 0.9 * 0.85)\n    print(f\"  {hp:2d} HP -> ~{fla:.1f} A FLA\")\n"}, {"tier": "Compounded", "g": "Panels & Distribution", "title": "Transformers: Sizing and Wiring", "desc": "Transformers change voltage by turns ratio - step down 480 to 208/120 for utilization, or 480 to 240/120 for small commercial. Delta-wye is the standard distribution connection: delta primary (no neutral needed), wye secondary with a neutral for 120 V loads. KVA sizing covers the load with growth margin; impedance (typically 2-6%) sets fault current.\nWiring discipline: primary and secondary protection per 450.3, grounding the wye neutral (XO) per 250.30 for separately derived systems, and bonding the enclosure. Buck-boost transformers tweak voltage for long runs. Dry-types hum - mount with vibration isolation away from quiet spaces.", "how": "Electricians compute load KVA (single-phase: V*A/1000; three-phase: V*A*1.73/1000), select the next standard size up (15, 30, 45, 75, 112.5...), protect primary and secondary per 450.3 tables, ground XO for separately derived systems, and bond everything. They check tap settings against measured voltage, torque lugs, and verify phase rotation matches the system before energizing.", "keys": ["Turns ratio sets voltage; delta-wye is the distribution standard.", "KVA sizing with growth margin; impedance sets fault current.", "Primary/secondary protection per 450.3.", "Ground XO on separately derived wye secondaries.", "Verify taps and rotation before energizing."], "reqs": ["Load KVA by voltage and phase.", "Primary voltage and desired secondary.", "Fault-current check from impedance."], "stds": ["Transformers per NEC Article 450.", "Grounding per NEC 250.30."], "cites": ["NFPA 70. National Electrical Code (NEC).", "Herman SL. Electrical Transformers (Delmar)."], "demo": "#!/usr/bin/env python3\n\"\"\"Transformer KVA sizing, 3-phase.\"\"\"\nimport math\nloads_va = [15000, 22000, 18000]  # per phase-ish\ntotal = sum(loads_va)\nkva = total / 1000\nstd = [15, 30, 45, 75, 112.5, 150]\nsize = next(s for s in std if s >= kva * 1.25)\nprint(f\"Load {kva:.0f} kVA -> select {size} kVA (25% margin)\")\n"}, {"tier": "Compounded", "g": "Wiring & Devices", "title": "Low-Voltage Systems", "desc": "Low-voltage systems - doorbells, thermostats, landscape lighting, network, security, audio - run alongside power wiring under relaxed rules (NEC Article 725, Class 2/3) but demand their own discipline: separation from line voltage, proper cable ratings (CL2/CL3, plenum where required), and power supplies sized to the load.\nThermostats wire R, W, Y, G, C - the C (common) wire powers smart thermostats, and its absence is the top smart-stat callback. Landscape lighting runs 12 V with voltage-drop discipline (heavier wire, hub wiring). Network cable (Cat6) respects bend radius and termination standards. The electrician who handles low-voltage cleanly owns the whole job.", "how": "Electricians keep Class 2/3 wiring separated from power (different boxes or barriers), use rated cable for the environment (plenum in air-handling spaces), pull thermostat cable with spare conductors including C, and size low-voltage transformers to the load with headroom. They test continuity and shorts before connecting equipment, label both ends, and document the system - low-voltage is only 'simple' until it fails mysteriously.", "keys": ["Class 2/3 wiring under Article 725 - relaxed but disciplined.", "Separate from line voltage; rated cable by environment.", "Pull the C wire - smart thermostats need it.", "Landscape 12 V needs voltage-drop discipline.", "Label both ends; test before connecting gear."], "reqs": ["System voltage class and power supply sizing.", "Cable rating for the environment.", "Separation from power wiring."], "stds": ["Class 2/3 per NEC Article 725.", "Network per TIA-568."], "cites": ["NFPA 70. National Electrical Code (NEC).", "BICSI installation guidance."], "demo": "#!/usr/bin/env python3\n\"\"\"Landscape lighting voltage drop (12V, hub method).\"\"\"\n# 12 AWG pair: 3.18 ohm/1000ft round trip-ish\nrun_ft, load_a = 80.0, 8.0\nvd = load_a * 3.18 / 1000 * run_ft\nprint(f\"VD = {vd:.1f} V on 12V ({vd/12*100:.0f}% - keep under 10%)\")\n"}, {"tier": "Compounded", "g": "Code & Safety", "title": "Smoke and CO Detector Circuits", "desc": "Smoke and CO alarms are life-safety devices with their own rules: hardwired with battery backup, interconnected so one sounds all (wireless interconnection now accepted), in every bedroom, outside sleeping areas, and on every level including basements. CO alarms guard fuel-burning appliances and attached garages.\nPlacement avoids nuisance: not in kitchens (cooking steam) or steamy bathrooms - photoelectric near kitchens reduces cooking alarms. Ten-year sealed batteries are the modern standard; the devices themselves expire in 7-10 years and must be replaced. The electrician wires the interconnect (usually the red/orange third wire) and tests the chain at trim.", "how": "Electricians lay out alarms per NFPA 72 and local amendments (which often exceed NEC), run the interconnect daisy-chain, keep them on a shared lighting circuit or dedicated (local rule), and test the all-sound chain at trim. They mount per clearances (4 inches from walls on ceilings, peaks of vaulted ceilings), document expiry dates for the homeowner, and verify CO placement near sleeping areas and fuel appliances.", "keys": ["Hardwired + battery backup, interconnected to sound all.", "Every bedroom, outside sleeping areas, every level.", "CO alarms at fuel appliances and attached garages.", "Avoid kitchens/baths for nuisance; photoelectric near cooking.", "Devices expire in 7-10 years - replace on schedule."], "reqs": ["Layout per NFPA 72 and local amendments.", "Interconnect wiring (3-wire or wireless).", "Expiry-date documentation."], "stds": ["Alarm placement per NFPA 72.", "Power per NEC 760 / local rules."], "cites": ["NFPA 72. National Fire Alarm and Signaling Code.", "NFPA 70. National Electrical Code (NEC)."], "demo": "#!/usr/bin/env python3\n\"\"\"Alarm count for a two-story 4-bedroom home.\"\"\"\nbedrooms, levels = 4, 2\nalarms = bedrooms + bedrooms + levels  # in each + outside each + per level\nprint(f\"Smoke alarms: ~{alarms} (bedrooms + halls + levels)\")\nprint(\"Add CO: near sleeping areas + fuel appliances + garage\")\n"}, {"tier": "Compounded", "g": "Code & Safety", "title": "Kitchen and Bathroom Code Requirements", "desc": "Kitchens and bathrooms concentrate the NEC's protection rules where water meets electricity. Kitchens: two 20 A small-appliance circuits minimum, GFCI on all receptacles serving countertops, receptacle spacing (no point along the counter more than 24 inches from one), dedicated circuits for fixed appliances, AFCI per dwelling rules.\nBathrooms: dedicated 20 A circuit (can serve multiple bathrooms' receptacles or one bathroom fully), GFCI on all receptacles, receptacle within 3 ft of each basin. Island and peninsular countertops have their own receptacle rules (2023 cycle changed them). Range and dryer circuits: 4-wire now, grounded properly - the 3-wire grandfathering is history for new work.", "how": "Electricians lay out countertop receptacles to the spacing rules first, then assign the two small-appliance circuits, GFCI-protect everything at the counter, and run dedicated homeruns for fixed appliances per nameplate. Bathrooms get the 20 A receptacle circuit with GFCI, fan on appropriate control (timer/humidistat), and lighting per plan. They verify island/peninsula compliance with the current cycle's wording - it changed recently.", "keys": ["Kitchens: two 20 A small-appliance circuits minimum.", "GFCI on countertop and bathroom receptacles.", "Counter receptacle spacing: 24-inch rule.", "Bathrooms: 20 A receptacle circuit, basin within 3 ft.", "Island/peninsula rules changed in 2023 - check the cycle."], "reqs": ["Countertop linear footage for spacing.", "Fixed-appliance nameplates.", "Locally adopted code cycle."], "stds": ["Kitchens/baths per NEC 210.8, 210.11(C), 210.52.", "GFCI per NEC 210.8(A)."], "cites": ["NFPA 70. National Electrical Code (NEC).", "Hartman T. Ugly's Electrical References. Jones & Bartlett."], "demo": "#!/usr/bin/env python3\n\"\"\"Countertop receptacles for a 12-ft run.\"\"\"\nimport math\nlength_ft = 12.0\n# max 24 in from any point -> spacing <= 48 in\nn = math.ceil(length_ft * 12 / 48) + 1\nprint(f\"{length_ft:.0f}-ft counter needs >= {n} receptacles\")\n"}, {"tier": "Compounded", "g": "Troubleshooting", "title": "Troubleshooting Dead Circuits", "desc": "Dead circuits get a disciplined sequence: verify at the panel (breaker tripped? voltage at the breaker?), then divide and conquer - check the midpoint receptacle to halve the search, following voltage until it disappears. The fault is between the last live point and the first dead one.\nCommon causes ranked: tripped breaker/GFCI/AFCI (reset once, investigate if it retrips), failed backstab connection (the classic), broken wire (nail/screw), failed device, open neutral (the dangerous one - 240 V across 120 V loads). Half-splitting beats random outlet-pulling every time.", "how": "Electricians confirm the scope (one receptacle or whole circuit?), check the breaker and any GFCI/AFCI in the path, then measure at the midpoint: voltage present means the fault is downstream. They pull devices looking for backstabs and loose screws, wiggle-test with the meter watching, and megger suspect runs. Open neutrals get immediate respect - unbalanced voltage destroys equipment. Every fix is verified under load before closing.", "keys": ["Divide and conquer: midpoint test halves the search.", "Fault lies between last live and first dead point.", "Check breaker/GFCI/AFCI first - reset once, then investigate.", "Backstabs are the classic failure; open neutrals the dangerous one.", "Verify under load before closing up."], "reqs": ["Circuit map or panel directory.", "Meter and basic hand tools.", "Load to verify the fix."], "stds": ["Safe troubleshooting per NFPA 70E.", "Device replacement per NEC 406."], "cites": ["NFPA 70E. Standard for Electrical Safety in the Workplace.", "Hartman T. Ugly's Electrical References. Jones & Bartlett."], "demo": "#!/usr/bin/env python3\n\"\"\"Half-split search: worst-case checks on N devices.\"\"\"\nimport math\nfor n in (4, 8, 16, 32):\n    print(f\"  {n:2d} devices: half-split {math.ceil(math.log2(n))} checks vs {n} linear\")\n"}, {"tier": "Compounded", "g": "Troubleshooting", "title": "Megger Insulation Testing", "desc": "The megohmmeter (megger) tests insulation by applying high DC voltage (250-1000 V) and reading leakage resistance in megohms: good insulation reads hundreds of megohms; deteriorated reads low; failed reads near zero. It finds nicked insulation, moisture ingress, and heat damage that a multimeter's 9 V cannot see.\nTest de-energized and isolated - disconnect electronics first (1000 V kills what 120 V merely annoys). Readings trend: compare phase to phase and to ground, and against history. Temperature corrects readings (insulation resistance halves roughly every 10 C rise). The polarization index (10-min/1-min ratio) judges large motors and transformers.", "how": "Electricians isolate the circuit or motor, verify dead, disconnect sensitive electronics, and megger phase-to-ground and phase-to-phase at the rated test voltage (typically 1000 V for 600 V equipment). They record readings with temperature, compare against minimums (1 megohm per kV is the rough rule, trending matters more), and investigate low readings by sectionalizing. Motors get PI tests on a schedule; failed insulation gets replaced, not wished better.", "keys": ["High DC voltage reveals insulation faults meters miss.", "Test de-energized, isolated, electronics disconnected.", "Trend readings; compare phases; correct for temperature.", "1 megohm per kV rough minimum; trending beats thresholds.", "Polarization index judges large rotating machines."], "reqs": ["De-energized, isolated test object.", "Test voltage matched to equipment rating.", "Temperature record for correction."], "stds": ["Insulation testing per IEEE 43 (motors).", "Test voltages per NETA ATS."], "cites": ["IEEE 43. Recommended Practice for Testing Insulation Resistance of Electric Machinery.", "NETA ATS. Acceptance Testing Specifications."], "demo": "#!/usr/bin/env python3\n\"\"\"Temperature correction of insulation resistance.\"\"\"\n# halves per 10C rise; correct to 40C base\nreading, T = 50.0, 60.0  # Mohm at 60C\ncorrected = reading * 2 ** ((T - 40) / 10)\nprint(f\"{reading} Mohm at {T}C -> {corrected:.0f} Mohm corrected to 40C\")\n"}, {"tier": "Advanced", "g": "Industrial", "title": "Motor Branch Circuit Sizing", "desc": "Motor circuits size differently from general wiring because motors draw 6x inrush: conductors at 125% of motor FLA (430.22), short-circuit protection sized large enough to allow starting (up to 250% for inverse-time breakers, 430.52) while overload relays - sized near FLA - provide the running protection. The breaker guards the wire from faults; the overload guards the motor from overheating.\nTables 430.247-250 give FLA by HP when nameplates are missing; 430.24 covers multiple motors (125% of largest plus the rest). Disconnects within sight (430.102), controllers rated for the HP (430.83), and locked-rotor considerations for large machines complete the design. VFD-fed motors add line/load reactors and shaft grounding to the conversation.", "how": "Electricians take FLA from the nameplate (or tables), size conductors at 125%, select the short-circuit device from 430.52 (starting large, adjusting down if nuisance trips allow), and set overloads to FLA per 430.32. They verify the disconnect is in sight of the motor and controller, torque terminations, and record settings on the panel schedule. Commissioning measures running current per phase against FLA and checks rotation.", "keys": ["Conductors at 125% FLA; breakers sized to allow starting (to 250%).", "Breaker guards wire from faults; overload guards motor from heat.", "FLA from nameplate, or Tables 430.247-250.", "Disconnect within sight of the motor.", "VFD motors add reactors and shaft grounding."], "reqs": ["Motor nameplate (HP, FLA, voltage, phase).", "Starting method (across-line, soft start, VFD).", "Controller and disconnect HP ratings."], "stds": ["Motor circuits per NEC Article 430.", "FLA tables 430.247-250."], "cites": ["NFPA 70. National Electrical Code (NEC).", "Herman SL. Industrial Motor Control. Cengage."], "demo": "#!/usr/bin/env python3\n\"\"\"Motor circuit: 25 HP, 460V, inverse-time breaker.\"\"\"\nfla = 34.0  # from table/nameplate\ncond_min = fla * 1.25\nbrk_max = fla * 2.50\nprint(f\"Conductor >= {cond_min:.1f} A; breaker <= {brk_max:.0f} A (next standard down)\")\nprint(f\"Overload set ~{fla:.0f} A\")\n"}, {"tier": "Advanced", "g": "Industrial", "title": "Variable Frequency Drives", "desc": "Variable frequency drives control motor speed by synthesizing variable-frequency AC: rectifier to DC bus, then IGBT inverter to PWM output. Benefits: soft starting (no 6x inrush), speed matching to load (fan/pump affinity laws make energy savings cubic), and process control. Costs: harmonics back into the supply, motor bearing currents (fluting), and insulation stress from voltage spikes on long leads.\nMitigations are standard: line reactors or DC chokes for harmonics, load reactors or dv/dt filters for long motor leads, shaft grounding rings or insulated bearings for bearing currents, inverter-duty motors for the voltage stress. Programming covers accel/decel ramps, min/max speeds, and protection (overload, phase loss). Commissioning verifies the motor actually sees clean power.", "how": "Electricians size VFDs to motor FLA (not HP alone), mount with ventilation clearances, wire with shielded VFD cable grounded at both ends (or per manufacturer), and keep motor leads short or add filters. They program motor data from the nameplate, set ramps and limits, enable protections, and verify rotation, current balance, and bearing temperature at commissioning. Harmonics get measured where the utility or sensitive loads complain - then reactors or filters.", "keys": ["Rectifier to DC bus, IGBT inverter to variable-frequency output.", "Affinity laws: pump/fan power follows speed cubed.", "Harmonics, bearing currents, lead-length spikes: the three mitigations.", "Shielded cable, short leads or filters, shaft grounding.", "Program from the nameplate; commission with measurements."], "reqs": ["Motor nameplate data and inverter-duty rating.", "Lead length and cable type.", "Harmonic environment assessment."], "stds": ["VFD installation per manufacturer + NEC 430.", "Harmonics per IEEE 519."], "cites": ["NFPA 70. National Electrical Code (NEC).", "Herman SL. Industrial Motor Control. Cengage."], "demo": "#!/usr/bin/env python3\n\"\"\"Affinity law: fan at 80% speed.\"\"\"\nspeed_ratio = 0.8\nflow = speed_ratio\npower = speed_ratio ** 3\nprint(f\"Speed {speed_ratio*100:.0f}% -> flow {flow*100:.0f}%, power {power*100:.0f}%\")\nprint(f\"Energy saved: {(1-power)*100:.0f}%\")\n"}, {"tier": "Advanced", "g": "Industrial", "title": "PLC-Controlled Systems", "desc": "Programmable logic controllers are the industrial electrician's computer: inputs (sensors, switches) feed the processor, ladder-logic programs decide, outputs (contactors, valves, drives) act - scanning the program in milliseconds. I/O modules handle 24 VDC digital, analog (4-20 mA, 0-10 V), and specialty signals; networks (Ethernet/IP, Profinet) link PLCs, drives, and HMIs.\nThe electrician's PLC work is wiring and field troubleshooting: landing I/O correctly (sinking vs sourcing!), verifying 24 V supplies, forcing I/O to test (with safety discipline), and reading ladder logic to find the failed rung. Program changes belong to controls engineers, but the electrician who reads ladder logic diagnoses in minutes what others chase for hours.", "how": "Electricians wire PLC I/O per the drawings - checking sinking/sourcing before landing a single wire - separate AC and DC in the panel, fuse I/O groups, and label everything. They troubleshoot with the status LEDs and online monitoring: input on but rung false means logic; rung true but output off means field wiring or the module. Forcing outputs is done with the process made safe first. Backups of programs are treated as gold - verify the backup before any download.", "keys": ["Inputs decide, ladder logic reasons, outputs act - millisecond scans.", "Sinking vs sourcing must match before landing wires.", "LEDs + online monitoring separate logic faults from field faults.", "Force I/O only with the process made safe.", "Program backups are gold - verify before downloading."], "reqs": ["I/O list with signal types.", "Sinking/sourcing determination.", "Program backup before changes."], "stds": ["PLC panels per UL 508A.", "Safety PLCs per ISO 13849 / IEC 62061."], "cites": ["Hughes T. Programmable Controllers. ISA.", "Herman SL. Industrial Motor Control. Cengage."], "demo": "#!/usr/bin/env python3\n\"\"\"Scan-time budget: program vs I/O.\"\"\"\nio_ms, logic_ms = 2.0, 5.0\nscan = io_ms + logic_ms\nprint(f\"Scan = {scan:.0f} ms -> {1000/scan:.0f} scans/sec\")\nprint(\"Keep scan under process time-constant / 10\")\n"}, {"tier": "Advanced", "g": "Renewables", "title": "Solar PV Installation Basics", "desc": "Solar PV turns electricians into power-plant builders: modules in series strings (voltage adds) feed inverters that synchronize to the grid, with rapid-shutdown (690.12) making conductors safe for firefighters, and 690.8 sizing conductors at 125% of continuous current. String sizing balances inverter MPPT windows against cold-weather Voc (record cold raises voltage).\nRoof work adds flashing and rail mounting that must not leak; ground mounts need trenching and concrete. Interconnection follows utility rules and NEC 705; production metering and monitoring prove performance. Commissioning tests: open-circuit voltage and polarity per string, insulation resistance, inverter startup, and production vs expected.", "how": "Electricians design strings within inverter voltage/MPPT windows at temperature extremes, size conductors and OCPD per 690.8/690.9, install rapid-shutdown devices per 690.12, and label per 690.31/56 (the red labels inspectors check). They flash mounts to roofing manufacturer specs, torque module clamps, manage wire with UV-rated methods, and commission string by string before the inverter goes live. Monitoring gets verified - unmonitored systems underperform silently.", "keys": ["Strings in series: voltage adds; size within MPPT and Voc limits.", "Conductors at 125% continuous per 690.8.", "Rapid shutdown per 690.12 - firefighter safety.", "Cold weather raises Voc - design for record cold.", "Commission per string: Voc, polarity, insulation, production."], "reqs": ["Inverter specs (MPPT window, max Voc).", "Record-low temperature for Voc calc.", "Utility interconnection requirements."], "stds": ["PV per NEC Article 690; interconnection per 705.", "Rapid shutdown per NEC 690.12."], "cites": ["NFPA 70. National Electrical Code (NEC).", "SEI. Solar Electric Handbook."], "demo": "#!/usr/bin/env python3\n\"\"\"String Voc at record cold (-20C).\"\"\"\nmodules, voc_stc, temp_coef = 12, 41.0, -0.003\ndelta_T = -20 - 25\nvoc_cold = modules * voc_stc * (1 + temp_coef * delta_T)\nprint(f\"String Voc cold: {voc_cold:.0f} V (inverter max 600/1000V check)\")\n"}, {"tier": "Advanced", "g": "Renewables", "title": "EV Charger Installation", "desc": "EV chargers are continuous loads that reshape residential services: Level 1 (120 V, 12 A - overnight trickle), Level 2 (240 V, up to 80 A - the home standard, usually 40-60 A circuits), DC fast charging (commercial). NEC 625 sizes conductors and OCPD at 125% of the charger rating; load management systems can share capacity across chargers without service upgrades.\nInstallation realities: service capacity checks (many 100 A services need load management or upgrades for a 60 A charger), GFCI requirements evolving by cycle, disconnect within sight for large units, and utility rate structures (time-of-use favors overnight charging). Commercial sites add networking, billing, and ADA considerations.", "how": "Electricians verify service capacity with an Article 220 calc including the EVSE at 125%, propose load management where the service is tight, run the dedicated circuit with GFCI per the adopted cycle, and mount the charger per manufacturer clearances. They configure amperage settings to match the installed circuit (the #1 commissioning error is a 60 A setting on a 50 A circuit), test GFCI and ground-fault functions, and walk the owner through scheduling for off-peak rates.", "keys": ["Level 2 (240 V, 40-60 A circuits) is the home standard.", "Size at 125% continuous per NEC 625.", "Service capacity check first - many 100 A services are tight.", "Load management avoids service upgrades.", "Match charger amperage setting to the installed circuit."], "reqs": ["EVSE nameplate and adjustable range.", "Service load calc with EVSE included.", "Utility rate and interconnection info."], "stds": ["EVSE per NEC Article 625.", "Load management per NEC 625.42."], "cites": ["NFPA 70. National Electrical Code (NEC).", "Hartman T. Ugly's Electrical References. Jones & Bartlett."], "demo": "#!/usr/bin/env python3\n\"\"\"EVSE circuit: 48A charger.\"\"\"\ncharger_a = 48.0\ncircuit_a = charger_a * 1.25\nimport math\nstd = [15, 20, 30, 40, 50, 60, 70, 80]\nbrk = next(s for s in std if s >= circuit_a)\nprint(f\"48A charger -> {circuit_a:.0f}A -> {brk}A circuit (6 AWG Cu typical)\")\n"}, {"tier": "Advanced", "g": "Industrial", "title": "Hazardous Location Wiring", "desc": "Hazardous locations - where flammable gases, vapors, dusts, or fibers may ignite - classify by Class (I gas, II dust, III fibers), Division (1 normal, 2 abnormal), and Group (gas type, A-D). NEC Articles 500-516 govern: explosionproof enclosures contain internal explosions (Class I Div 1), intrinsically safe circuits limit energy below ignition (ideal for instruments), purged/pressurized enclosures keep gas out.\nWiring methods are restricted: rigid metal conduit or MI cable in Div 1, with sealing fittings at boundaries to stop flame propagation through the raceway. Equipment must be listed for the classification - ordinary devices are ignition sources. Area classification drawings come from the engineer; the electrician installs exactly to them.", "how": "Electricians work from the area-classification drawings - never guessing boundaries - install listed equipment rated for the Class/Division/Group, run rigid conduit with seals at every boundary (poured per listing), and keep intrinsically safe wiring separated and identified (blue is the convention). They torque explosionproof covers with all bolts (flame paths depend on it), never drill unlisted holes, and document every seal location. Inspectors in classified areas show no mercy - the stakes are explosions.", "keys": ["Class/Division/Group defines the hazard and the rules.", "Explosionproof contains; intrinsically safe cannot ignite; purged excludes.", "Seals at every boundary stop flame through raceways.", "All bolts in explosionproof covers - flame paths depend on it.", "Install to the classification drawing - never guess."], "reqs": ["Area classification drawings.", "Equipment listed for the classification.", "Seal fittings and compound per listing."], "stds": ["Hazardous locations per NEC Articles 500-516.", "Seals per NEC 501.15."], "cites": ["NFPA 70. National Electrical Code (NEC).", "UL 1203. Explosion-Proof Enclosures."], "demo": "#!/usr/bin/env python3\n\"\"\"Classification lookup (reference).\"\"\"\nclasses = {\"I\": \"gases/vapors\", \"II\": \"dusts\", \"III\": \"fibers\"}\ndivs = {\"1\": \"normal conditions\", \"2\": \"abnormal conditions\"}\nfor c, d in classes.items():\n    print(f\"  Class {c}: {d}; Div 1 = {divs[\"1\"]}, Div 2 = {divs[\"2\"]}\")\n"}, {"tier": "Advanced", "g": "Industrial", "title": "Backup Generators and Transfer Switches", "desc": "Backup generators keep the lights on: standby units (natural gas/propane, automatic transfer) for homes and businesses, portable units (manual transfer, cord-connected) for essentials. NEC Article 702 (optional standby), 700 (emergency - life safety, 10-second transfer), and 701 (legally required) set the rules by criticality.\nTransfer switches are the safety heart: they isolate the generator from the utility so backfeed cannot electrocute lineworkers - the interlocked breaker kit is the minimum legal transfer means. Sizing: the generator must carry the calculated load with motor-starting surge; automatic switches need exercise timers. Fuel, clearances, and noise ordinances complete the install.", "how": "Electricians size generators from the load calc with starting KVA of the largest motor, select transfer equipment rated for the service (service-entrance-rated where it is the disconnect), wire with proper neutral/ground handling (switched neutral for separately derived), and set exercise schedules. They verify transfer under load at commissioning, label the system per 702, and warn against suicide cords - the transfer switch exists because backfeed kills lineworkers.", "keys": ["Transfer switch isolates generator from utility - backfeed kills.", "Article 700/701/702 by criticality: 10-second rule for emergency.", "Size for load plus largest motor's starting surge.", "Exercise timers keep standby units ready.", "No suicide cords - ever."], "reqs": ["Load calc with motor-starting KVA.", "Transfer switch rated for the service.", "Fuel supply and clearances."], "stds": ["Standby systems per NEC 700/701/702.", "Transfer per UL 1008."], "cites": ["NFPA 70. National Electrical Code (NEC).", "NFPA 110. Emergency Power Systems."], "demo": "#!/usr/bin/env python3\n\"\"\"Generator sizing with motor start.\"\"\"\nrunning_kw, largest_motor_kva = 18.0, 25.0\nother_kw = running_kw - 8.0\ngen_kva = other_kw / 0.8 + largest_motor_kva  # rough\nimport math\nstd = [20, 25, 30, 40, 50, 60]\nsize = next(s for s in std if s >= gen_kva)\nprint(f\"Need ~{gen_kva:.0f} kVA -> select {size} kVA standby\")\n"}, {"tier": "Advanced", "g": "Code & Safety", "title": "Arc-Flash Studies and Labeling", "desc": "Arc-flash studies quantify the hazard: available fault current and clearing time at each piece of gear produce incident energy (cal/cm2) and the arc-flash boundary, which NFPA 70E turns into PPE requirements. Labels on gear (NEC 110.16) carry the numbers - nominal voltage, boundary, incident energy, PPE category - so the electrician knows the risk before opening the door.\nThe study needs accurate inputs: utility fault current, transformer impedance, conductor lengths and sizes, breaker settings. Reducing incident energy means faster clearing (current-limiting fuses, maintenance mode on breakers) or more distance. Studies expire when the system changes - a transformer swap can invalidate the labels.", "how": "Electricians collect field data for the engineer (gear models, breaker settings, conductor runs), apply the labels the study produces, and work to them: PPE matching the incident energy, tools and boundaries per 70E. They trigger study updates when equipment changes, use maintenance-mode settings where provided during the work, and never assume an unlabeled panel is low-energy. The label is read before the door opens - always.", "keys": ["Study outputs: incident energy and boundary per location.", "Labels per NEC 110.16 carry voltage, boundary, energy, PPE.", "Faster clearing = less energy: fuses, maintenance mode.", "System changes invalidate studies - update on changes.", "Read the label before opening the door."], "reqs": ["Utility fault current and system one-line.", "Breaker settings and conductor data.", "Qualified engineer for the study."], "stds": ["Arc flash per IEEE 1584; safety per NFPA 70E.", "Labeling per NEC 110.16."], "cites": ["IEEE 1584. Guide for Arc-Flash Hazard Calculations.", "NFPA 70E. Standard for Electrical Safety in the Workplace."], "demo": "#!/usr/bin/env python3\n\"\"\"Incident energy vs clearing time (illustrative).\"\"\"\n# energy roughly proportional to clearing time at fixed fault current\nfor t in (0.05, 0.2, 0.5, 1.0):\n    e = 8.0 * t / 0.2  # cal/cm2 scaled\n    ppe = 1 if e < 4 else (2 if e < 8 else (3 if e < 25 else 4))\n    print(f\"  clearing {t:.2f}s -> ~{e:.1f} cal/cm2 (PPE cat {ppe})\")\n"}, {"tier": "Advanced", "g": "Troubleshooting", "title": "Power Quality Investigations", "desc": "Power quality is the electricity behaving: sags, swells, transients, harmonics, and unbalance that upset sensitive equipment while meters read 'normal voltage.' The investigator's tools: power-quality analyzers that log waveforms, harmonic spectra, and events over days.\nCommon findings: harmonics from VFDs and LED drivers (neutral overload in shared-neutral systems), voltage sags from utility switching or large motor starts, transients from capacitor switching or lightning, unbalance from single-phase loading. Fixes: K-rated transformers and oversized neutrals for harmonics, surge protection at service and point-of-use, load balancing, and utility coordination for sags.", "how": "Electricians interview the symptoms (what misbehaves, when, with what else running), install the analyzer at the suspect panel for a representative period, and correlate events with equipment logs. They check neutral currents for triplen harmonics, measure unbalance, inspect grounding and bonding (the cause of half of 'power quality' complaints), and implement the fix the data supports - not the one guessed first. Reports document before/after.", "keys": ["Sags, swells, transients, harmonics, unbalance: the five disturbances.", "Log over days - spot meters miss intermittent events.", "Harmonics overload shared neutrals; check neutral current.", "Half of 'power quality' complaints are grounding/bonding.", "Correlate events with equipment logs; fix what the data shows."], "reqs": ["Symptom timeline and affected equipment.", "Analyzer logging at the suspect panel.", "Grounding/bonding verification."], "stds": ["PQ measurement per IEC 61000-4-30.", "Harmonics per IEEE 519."], "cites": ["IEEE 1159. Recommended Practice for Monitoring Electric Power Quality.", "Dugan RC et al. Electrical Power Systems Quality. McGraw-Hill."], "demo": "#!/usr/bin/env python3\n\"\"\"Neutral current with triplen harmonics (illustrative).\"\"\"\n# 3rd harmonics add in the neutral instead of canceling\nphase_a = 20.0\nthird_harm_pct = 0.35\nneutral = 3 * phase_a * third_harm_pct\nprint(f\"Phase {phase_a}A with 35% 3rd harmonic -> neutral ~{neutral:.0f}A\")\nprint(\"(exceeds phase current - size neutral at 200% or use K-rated)\")\n"}, {"tier": "Advanced", "g": "Career", "title": "Apprenticeship to Master Electrician", "desc": "The trade runs on a ladder: apprentice (4-5 years, ~8,000 hours on-the-job plus classroom, typically through union JATC or non-union ABC/IEC programs), journeyman (licensed, works independently), master (years more, plans and pulls permits, runs work). Licensing is state-by-state - hours, exams, and reciprocity all vary.\nClassroom covers code, theory, and safety while OJT builds the hands: rough-in, trim, conduit, troubleshooting, and increasingly PLC, solar, and EV. Pay rises with each step; masters who run crews or shops earn at the top of the skilled trades. Continuing education keeps the license current with each code cycle. The path rewards patience - the license is the asset.", "how": "Aspiring electricians enter through JATC, ABC/IEC, or company programs, log hours honestly, study code systematically (not just the exam), and seek varied OJT - residential, commercial, industrial - because breadth makes the journeyman. They test for journeyman when hours qualify, then master after the required years, choosing specialties (controls, solar, service) that command premiums. The license is maintained with CEUs and clean work - reputation compounds.", "keys": ["Apprentice 4-5 years (~8,000 hours) + classroom.", "Journeyman works independently; master plans and permits.", "Licensing is state-by-state; know your state's rules.", "Varied OJT (res/comm/industrial) builds the valuable journeyman.", "The license is the asset - CEUs keep it current."], "reqs": ["Program enrollment (JATC/ABC/IEC/company).", "Hour logging and classroom completion.", "State exam qualification."], "stds": ["Training per DOL apprenticeship standards.", "Licensing per state boards."], "cites": ["U.S. DOL. Apprenticeship program standards.", "NECA/IBEW JATC training curricula."], "demo": "#!/usr/bin/env python3\n\"\"\"Apprenticeship hour progress.\"\"\"\nrequired, logged = 8000, 5250\npct = logged / required * 100\nprint(f\"Hours: {logged}/{required} ({pct:.0f}%)\")\nprint(f\"Remaining: {required-logged} hrs (~{(required-logged)/2000:.1f} years at 2000/yr)\")\n"}];
function buildRecord(seed,topic,sig){
  var title=topic.title+(sig?' (Signature Edition)':'');
  var desc=topic.desc;
  if(sig)desc='Signature original treatment. '+desc;
  return {
    id:(sig?'JAH-ELTRS-':PREFIX)+String(seed).padStart(6,'0'),
    t:title, g:topic.g, name:title, title:title,
    description:desc,
    how_it_works:topic.how,
    key_points:topic.keys,
    requirements:topic.reqs,
    standards:topic.stds,
    citations:topic.cites,
    src:sig?'signature':'public-harvest',
    ladder_rank:seed,
    ladder_tier:topic.tier.toLowerCase(),
    demo:{kind:'python',language:'python',program:topic.demo,
      note:'Working demonstration program for this record.'},
    _seed:seed
  };
}
function topicFor(seed,opts){
  opts=opts||{};
  var pool=TOPICS.filter(function(t){return !opts.field||t.tier===opts.field;});
  if(!pool.length)pool=TOPICS;
  var i=((seed-1)%pool.length+pool.length)%pool.length;
  return {topic:pool[i],index:TOPICS.indexOf(pool[i])};
}
function generate(seed,opts){
  var tf=topicFor(seed,opts);
  var sig=(opts&&opts.signature)||false;
  return buildRecord(tf.index+1,tf.topic,sig);
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return {ok:false,errors:['not an object']};
  var okId=new RegExp('^('+PREFIX.replace(/-/g,'\\-')+'|'+'JAH-ELTRS-'.replace(/-/g,'\\-')+')\\d{6}$').test(r.id||'');
  if(!okId)e.push('id');
  if(FIELDS.indexOf(capTier(r.ladder_tier))<0)e.push('tier');
  if(['public-harvest','signature'].indexOf(r.src)<0)e.push('src');
  if(!r.title)e.push('title');
  if(!r.description||r.description.length<40)e.push('description');
  if(!r.demo||!r.demo.program||r.demo.program.indexOf('print')<0)e.push('demo');
  return {ok:!e.length,errors:e};
}
function capTier(s){s=String(s||'');return s.charAt(0).toUpperCase()+s.slice(1);}
function driftCheck(record,sample){
  var dups=(sample||[]).filter(function(r){return r&&r.title===record.title&&r.ladder_tier===record.ladder_tier;});
  return dups.length?{ok:false,errors:['duplicate title+tier in archive sample']}:{ok:true,errors:[]};
}
var gen={version:'jahdb-electricians-1.0',generate:generate,validate:validate,driftCheck:driftCheck,fields:FIELDS};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('electricians',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();
